UPDATE installed_apps
SET manifest_json=json_set(manifest_json,'$.print_formats',json('[{"name":"Hoá đơn ALUMDOOR","doc_type":"Sales Invoice","format_type":"Standard","html":"<div class=\"head\">\n  <div><div class=\"brand\">ALUMDOOR</div>\n  <div class=\"sub\">Cửa cuốn công nghệ Đức / Úc<br>Xưởng 1: 12B đường số 2, P. Bình Hưng Hoà, Q. Bình Tân, TP.HCM<br>Xưởng 2: 36 đường số 7, P. Bình Hưng Hoà, Q. Bình Tân, TP.HCM</div></div>\n  <div><div class=\"title\">Hoá đơn bán hàng</div><div class=\"no\">Số: {{ name }}<br>Ngày: {{ posting_at | date }}</div></div>\n</div>\n<div class=\"grid\">\n  <div class=\"row\"><b>Khách hàng</b><span>{{ customer }}</span></div>\n  <div class=\"row\"><b>Hạn thanh toán</b><span>{{ due_date | date }}</span></div>\n  <div class=\"row\"><b>Theo đơn hàng</b><span>{{ against_sales_order }}</span></div>\n  <div class=\"row\"><b>Tiền tệ</b><span>{{ currency }}</span></div>\n</div>\n<table><thead><tr><th style=\"width:34px\">#</th><th>Mã hàng</th><th class=\"n\">Số lượng</th><th class=\"n\">Đơn giá</th><th class=\"n\">Thành tiền</th></tr></thead><tbody>\n{{#each items}}<tr><td>{{ _index }}</td><td>{{ item_code }}</td><td class=\"n\">{{ qty | number }}</td><td class=\"n\">{{ rate | money }}</td><td class=\"n\">{{ amount | money }}</td></tr>{{/each}}\n</tbody></table>\n<div class=\"tot\">\n  <div class=\"row\"><span>Tổng cộng</span><span>{{ grand_total | money }} ₫</span></div>\n  <div class=\"row big\"><span>Còn phải thu</span><span>{{ outstanding_amount | money }} ₫</span></div>\n</div>\n<div class=\"sign\"><div><b>Người mua hàng</b>(ký, ghi rõ họ tên)</div><div><b>Người lập phiếu</b>(ký, ghi rõ họ tên)</div><div><b>Đại diện ALUMDOOR</b>(ký, đóng dấu)</div></div>","css":"*{box-sizing:border-box} body{font-family:''Segoe UI'',Roboto,Arial,sans-serif;font-size:13px;color:#111;margin:0;padding:24px}\n.head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #c1121f;padding-bottom:12px;margin-bottom:16px}\n.brand{font-size:22px;font-we